// Bells and beeps are synthesized with Web Audio. The spoken countdown and the
// "work" / "rest" announcements use short clips in public/voice/, generated by
// scripts/gen-voice.py.
import type { CountdownStyle, SoundKind, StepKind } from './engine';

let ctx: AudioContext | null = null;
// Limiter in front of the speakers so stacked partials can be loud without clipping.
let out: AudioNode | null = null;

const VOICE_FILES = ['three', 'two', 'one', 'work', 'rest'] as const;
const COUNTDOWN_CLIPS: Record<number, string> = { 3: 'three', 2: 'two', 1: 'one' };
const voice = new Map<string, AudioBuffer>();
let voiceLoading = false;

/** Must first be called from a user gesture (e.g. the Start click). */
export function unlockAudio(): void {
  if (!ctx) {
    ctx = new AudioContext();
    const limiter = ctx.createDynamicsCompressor();
    limiter.threshold.value = -6;
    limiter.knee.value = 0;
    limiter.ratio.value = 20;
    limiter.attack.value = 0.001;
    limiter.release.value = 0.1;
    limiter.connect(ctx.destination);
    out = limiter;
  }
  if (ctx.state === 'suspended') void ctx.resume();
  if (!voiceLoading) {
    voiceLoading = true;
    void loadVoice(ctx);
  }
}

async function loadVoice(audio: AudioContext): Promise<void> {
  await Promise.all(
    VOICE_FILES.map(async (name) => {
      try {
        const res = await fetch(`voice/${name}.mp3`);
        voice.set(name, await audio.decodeAudioData(await res.arrayBuffer()));
      } catch (err) {
        // Missing clip: playCountdown falls back to the beep; announcements are skipped.
        console.warn(`voice clip ${name} failed to load`, err);
      }
    }),
  );
}

function tone(freq: number, duration: number, type: OscillatorType, gain: number, at = 0): void {
  if (!ctx || !out) return;
  const t0 = ctx.currentTime + at;
  const osc = ctx.createOscillator();
  const amp = ctx.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  amp.gain.setValueAtTime(gain, t0);
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
  osc.connect(amp).connect(out);
  osc.start(t0);
  osc.stop(t0 + duration);
}

/** Plays a voice clip `at` seconds from now; false if it isn't loaded. */
function speak(name: string, at = 0): boolean {
  const clip = voice.get(name);
  if (!ctx || !clip) return false;
  const src = ctx.createBufferSource();
  src.buffer = clip;
  src.connect(ctx.destination);
  src.start(ctx.currentTime + at);
  return true;
}

/** Countdown cue for `second` (3, 2 or 1) seconds left. */
export function playCountdown(second: number, style: CountdownStyle): void {
  if (style === 'voice' && speak(COUNTDOWN_CLIPS[second])) return;
  tone(660, 0.12, 'sine', 0.4);
}

/** Says "Work" or "Rest" as that step starts; prep is silent. */
export function playAnnouncement(kind: StepKind): void {
  // Lands just after the transition sound's first hit so the two don't mask each other.
  if (kind !== 'prep') speak(kind, 0.35);
}

function bellStrike(at: number): void {
  tone(1150, 1.1, 'triangle', 0.7, at);
  tone(1150 * 2.76, 0.7, 'sine', 0.35, at);
  tone(1150 * 5.4, 0.4, 'sine', 0.2, at);
  tone(4200, 0.03, 'square', 0.25, at);
}

/** Played when a step starts. */
export function playTransition(kind: SoundKind): void {
  switch (kind) {
    case 'bell':
      // Boxing-ring double strike: a bright, high bell hit twice in quick
      // succession. Inharmonic partials read as metal; the short square click
      // gives each hit a hard attack.
      bellStrike(0);
      bellStrike(0.16);
      break;
    case 'beep':
      tone(990, 0.35, 'square', 0.2);
      break;
    case 'whistle':
      tone(2100, 0.5, 'triangle', 0.35);
      tone(2300, 0.5, 'triangle', 0.15);
      break;
  }
}

/**
 * Synthesized tiger roar starting `at` seconds from now on `audio`'s clock.
 * A low, detuned sawtooth growl is chopped by a fast LFO for the throat rasp,
 * distorted for grit, and pushed through a resonant filter that sweeps open and
 * shut like a mouth. Filtered noise on top supplies the breath.
 */
export function roar(audio: BaseAudioContext, dest: AudioNode, at = 0): void {
  const t0 = audio.currentTime + at;
  const len = 2.4;
  const end = t0 + len;

  const master = audio.createGain();
  master.gain.setValueAtTime(0.0001, t0);
  master.gain.exponentialRampToValueAtTime(0.9, t0 + 0.25);
  master.gain.setValueAtTime(0.9, t0 + 0.9);
  master.gain.exponentialRampToValueAtTime(0.5, t0 + 1.6);
  master.gain.exponentialRampToValueAtTime(0.0001, end);
  master.connect(dest);

  // Mouth: resonant low-pass that opens on the swell and closes on the tail.
  const mouth = audio.createBiquadFilter();
  mouth.type = 'lowpass';
  mouth.Q.value = 6;
  mouth.frequency.setValueAtTime(350, t0);
  mouth.frequency.exponentialRampToValueAtTime(1600, t0 + 0.5);
  mouth.frequency.exponentialRampToValueAtTime(900, t0 + 1.3);
  mouth.frequency.exponentialRampToValueAtTime(250, end);
  mouth.connect(master);

  const grit = audio.createWaveShaper();
  const curve = new Float32Array(1024);
  for (let i = 0; i < curve.length; i++) {
    const x = (i / (curve.length - 1)) * 2 - 1;
    curve[i] = Math.tanh(x * 4);
  }
  grit.curve = curve;
  grit.connect(mouth);

  // Rasp: amplitude modulation at ~30 Hz, the flutter of vocal folds.
  const rasp = audio.createGain();
  rasp.gain.value = 0.6;
  const lfo = audio.createOscillator();
  const lfoDepth = audio.createGain();
  lfo.frequency.setValueAtTime(34, t0);
  lfo.frequency.linearRampToValueAtTime(24, end);
  lfoDepth.gain.value = 0.4;
  lfo.connect(lfoDepth).connect(rasp.gain);
  rasp.connect(grit);
  lfo.start(t0);
  lfo.stop(end);

  // Growl: pitch climbs into the roar then sags as it runs out of breath.
  for (const detune of [1, 1.013, 0.5]) {
    const osc = audio.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(95 * detune, t0);
    osc.frequency.exponentialRampToValueAtTime(165 * detune, t0 + 0.45);
    osc.frequency.exponentialRampToValueAtTime(120 * detune, t0 + 1.4);
    osc.frequency.exponentialRampToValueAtTime(70 * detune, end);
    const g = audio.createGain();
    g.gain.value = detune === 0.5 ? 0.5 : 0.35;
    osc.connect(g).connect(rasp);
    osc.start(t0);
    osc.stop(end);
  }

  // Breath: band-passed noise riding along with the growl.
  const noise = audio.createBuffer(1, Math.ceil(audio.sampleRate * len), audio.sampleRate);
  const data = noise.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  const breath = audio.createBufferSource();
  breath.buffer = noise;
  const band = audio.createBiquadFilter();
  band.type = 'bandpass';
  band.frequency.value = 700;
  band.Q.value = 0.8;
  const breathGain = audio.createGain();
  breathGain.gain.value = 0.25;
  breath.connect(band).connect(breathGain).connect(rasp);
  breath.start(t0);
  breath.stop(end);
}

/** Played once when the workout finishes: three transition cues, then a roar. */
export function playFinish(kind: SoundKind): void {
  playTransition(kind);
  setTimeout(() => playTransition(kind), 450);
  setTimeout(() => playTransition(kind), 900);
  if (ctx && out) roar(ctx, out, 1.5);
}
